insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (270, 27, 1, 14, 'سورة النمل ١ – ١٤', '«طس تلك آيات القرآن وكتاب مبين»، و«إني آنست ناراً»، و«وجحدوا بها واستيقنتها أنفسهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 270) = $j$[{"lbl": "الآيات ١ – ٥", "q": "طسٓۚ تِلۡكَ ءَايَٰتُ ٱلۡقُرۡءَانِ وَكِتَابٖ مُّبِينٍ ﴿١﴾ هُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ ﴿٢﴾ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ﴿٣﴾ إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ﴿٤﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَهُمۡ سُوٓءُ ٱلۡعَذَابِ وَهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ ﴿٥﴾", "w": [["طس", "أحد الحروف المقطّعة، يُقرأ: طا سين."], ["تلك", "الآيات المؤلّفة من هذه الحروف آيات القرآن."], ["هدى وبشرى", "أعلام هداية للصراط المستقيم، وبشارة للمهتدين."], ["زيّنا لهم أعمالهم", "حبّبناها إليهم حسب سنّتنا فيمن لا يؤمن بالبعث والجزاء."], ["فهم يعمهون", "في ضلال بعيد وحيرة لا تنتهي."], ["لهم سوء العذاب", "في الدنيا بالأسر والقتل."]], "m": "طس، الله أعلم بمراده بذلك، وهذا أسلم، وفيها إشارة إلى أن القرآن المعجز تألّف من مثل هذه الحروف العربية، فألّفوا أيها العرب مثله، فإن عجزتم فآمنوا أنه كلام الله. تلك آيات القرآن وكتاب مبيّن لكل ما يُحتاج إلى بيانه من الحق والشرع، هادٍ إلى الصراط المستقيم المفضي إلى السعادة في الدارين، وبشارة عظمى للمؤمنين الذين يقيمون الصلاة بأدائها في أوقاتها مستوفاة الشروط والأركان، ويؤتون الزكاة عند وجوبها، وهم بالآخرة وما فيها من حساب وجزاء يوقنون. إن الذين لا يؤمنون بالآخرة حبّبنا إليهم أعمالهم، وهي شر وفساد، حسب سنّتنا فيمن أنكر البعث فلم يرهب حساباً ولا خاف عقاباً، فانغمس في الرذائل، فهم يتخبّطون لا يعرفون معروفاً ولا ينكرون منكراً. أولئك لهم سوء العذاب في الدنيا بالأسر والقتل، وهم في الآخرة أشد أهل النار خساراً.", "h": ["بيان إعجاز القرآن، إذ آياته مؤلّفة من مثل «طس» و«حم»، وعجز العرب عن تأليف مثله.", "بيان كون القرآن هدى وبشرى للمؤمنين الملتزمين بمتطلّبات الإيمان.", "إنكار البعث والدار الآخرة يجعل صاحبه شر الخليقة."], "k": "«الذين يقيمون الصلاة ويؤتون الزكاة وهم بالآخرة هم يوقنون»… البشرى لها شروط؛ فأيها أحتاج أن أقوّيه في نفسي؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِيمٍ عَلِيمٍ ﴿٦﴾ إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦٓ إِنِّيٓ ءَانَسۡتُ نَارٗا سَـَٔاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِيكُم بِشِهَابٖ قَبَسٖ لَّعَلَّكُمۡ تَصۡطَلُونَ ﴿٧﴾ فَلَمَّا جَآءَهَا نُودِيَ أَنۢ بُورِكَ مَن فِي ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٨﴾ يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٩﴾ وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ ﴿١٠﴾ إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوٓءٖ فَإِنِّي غَفُورٞ رَّحِيمٞ ﴿١١﴾", "w": [["وإنك لتُلقّى القرآن", "تُلقّنه وتحفظه وتعلّمه."], ["من لدن حكيم عليم", "من عند الله جل جلاله."], ["آنست ناراً", "أبصرت ناراً من بعيد حصل لي بها بعض الأنس."], ["سآتيكم منها بخبر", "عن الطريق، إذ ضلّوا طريقهم إلى مصر في الصحراء."], ["بشهاب قبس", "بشعلة نار مقبوسة مأخوذة من أصلها."], ["لعلكم تصطلون", "تستدفئون."], ["أن بورك من في النار", "بارك الله من في النار، وهو موسى ﵇ في البقعة المباركة."], ["تهتزّ كأنها جانّ", "تتحرك بسرعة كأنها حية خفيفة السرعة."], ["ولم يعقّب", "لم يرجع إليها خوفاً وفزعاً منها."], ["ثم بدّل حسناً بعد سوء", "تاب فعمل صالحاً بعد الذي حصل منه من السوء."]], "m": "ما زال السياق في تقرير النبوة المحمدية: وإنك لتُلقّى القرآن وتحفظه من لدن حكيم في تدبيره عليم بخلقه. اذكر للمكذّبين بنبوّتك إذ قال موسى لأهله في ليلة شاتية باردة وقد ضلّوا الطريق: إني أبصرت ناراً، سآتيكم منها بخبر عن الطريق، أو آتيكم بشعلة لعلكم تستدفئون؛ فهل مثل هذا يكون بغير تلقٍّ من الله؟ فلما جاءها نودي: أن بورك من في النار ومن حولها، وهو موسى ﵇ ومن حولها من أرض القدس والشام، والله أعلم بمراده من كلامه، وسبحان الله رب العالمين عما لا يليق بجلاله. يا موسى إنه أنا الله العزيز الحكيم. ثم أمره أن يلقي العصا تمريناً له على استعمالها، فلما رآها تهتزّ كأنها حية ولّى مدبراً ولم يرجع خوفاً، فناداه: يا موسى لا تخف، إني لا يخاف لديّ المرسلون، إلا من ظلم نفسه بذنب، فإن تاب وعمل حسناً بعد السوء فإني غفور رحيم. طمأنه بهذا لأنه كان يشعر بذنب قتل القبطي قبل نبوّته.", "h": ["تقرير النبوة المحمدية.", "مشروعية السفر بالأهل والولد، وجواز خطأ الطريق حتى على الأنبياء والأذكياء.", "قيّومية الرجل على النساء والأطفال.", "تجلّي الرب تعالى لموسى في البقعة المباركة ومناجاته وتدريبه على العصا التي يقاوم بها فرعون وملأه فيما بعد.", "الظلم يسبّب الخوف والعقوبة، إلا من تاب منه وأصلح، فإن الله غفور رحيم."], "k": "«ثم بدّل حسناً بعد سوء»… الباب لم يُغلق؛ فما السوء الذي أبدّله اليوم بحسن؟"}, {"lbl": "الآيات ١٢ – ١٤", "q": "وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿١٢﴾ فَلَمَّا جَآءَتۡهُمۡ ءَايَٰتُنَا مُبۡصِرَةٗ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ ﴿١٣﴾ وَجَحَدُواْ بِهَا وَٱسۡتَيۡقَنَتۡهَآ أَنفُسُهُمۡ ظُلۡمٗا وَعُلُوّٗاۚ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ﴿١٤﴾", "w": [["في جيبك", "جيب ثوبك."], ["من غير سوء", "من غير برص ونحوه، بل هو بياض إشراق."], ["في تسع آيات", "ضمن تسع آيات مرسلاً بها إلى فرعون."], ["مبصرة", "مضيئة واضحة مشرقة."], ["وجحدوا بها", "لم يُقرّوا بها ولم يعترفوا."], ["واستيقنتها أنفسهم", "أيقنوا أنها من عند الله."], ["ظلماً وعلوّاً", "ردّوها لأنهم ظالمون مستكبرون."]], "m": "بعد أن طمأن الله موسى أمره أن يدخل يده في جيب قميصه تخرج بيضاء من غير برص، بياض إشراق يكاد يذهب بالأبصار، ضمن تسع آيات مرسلاً بها إلى فرعون وقومه، إنهم كانوا قوماً خارجين عن الاعتدال إلى الإسراف في الشر والفساد. فلما جاءتهم آياتنا واضحة دالة على صدق موسى رفضوها وقالوا: هذا سحر مبين. وجحدوا بها وكذّبوا، وقد تيقّنتها أنفسهم أنها من عند الله، وإنما حملهم على التكذيب مع العلم ظلمهم واستكبارهم. فانظر يا رسولنا كيف كان عاقبة المفسدين، وهي إهلاكهم.", "h": ["آية اليد إحدى الآيات التسع التي أوتيها موسى ﵇.", "التنديد بالفسق، واستحقاق أهله العذاب في الدارين.", "الكبر والعلوّ في الأرض يجحد صاحبهما الحق ولا يقرّ به وهو يعلم أنه حق.", "عاقبة الفساد في الأرض بالمعاصي سوأى، والعياذ بالله تعالى."], "k": "«وجحدوا بها واستيقنتها أنفسهم»… قد أعرف الحق وأردّه كبراً؛ فهل في نفسي حق أعرفه ولا أعترف به؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 270;
insert into public.tdb_cards(topic, i, body) select 270, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "طسٓۚ تِلۡكَ ءَايَٰتُ ٱلۡقُرۡءَانِ وَكِتَابٖ مُّبِينٍ ﴿١﴾ هُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ ﴿٢﴾ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ﴿٣﴾ إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ﴿٤﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَهُمۡ سُوٓءُ ٱلۡعَذَابِ وَهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ ﴿٥﴾", "w": [["طس", "أحد الحروف المقطّعة، يُقرأ: طا سين."], ["تلك", "الآيات المؤلّفة من هذه الحروف آيات القرآن."], ["هدى وبشرى", "أعلام هداية للصراط المستقيم، وبشارة للمهتدين."], ["زيّنا لهم أعمالهم", "حبّبناها إليهم حسب سنّتنا فيمن لا يؤمن بالبعث والجزاء."], ["فهم يعمهون", "في ضلال بعيد وحيرة لا تنتهي."], ["لهم سوء العذاب", "في الدنيا بالأسر والقتل."]], "m": "طس، الله أعلم بمراده بذلك، وهذا أسلم، وفيها إشارة إلى أن القرآن المعجز تألّف من مثل هذه الحروف العربية، فألّفوا أيها العرب مثله، فإن عجزتم فآمنوا أنه كلام الله. تلك آيات القرآن وكتاب مبيّن لكل ما يُحتاج إلى بيانه من الحق والشرع، هادٍ إلى الصراط المستقيم المفضي إلى السعادة في الدارين، وبشارة عظمى للمؤمنين الذين يقيمون الصلاة بأدائها في أوقاتها مستوفاة الشروط والأركان، ويؤتون الزكاة عند وجوبها، وهم بالآخرة وما فيها من حساب وجزاء يوقنون. إن الذين لا يؤمنون بالآخرة حبّبنا إليهم أعمالهم، وهي شر وفساد، حسب سنّتنا فيمن أنكر البعث فلم يرهب حساباً ولا خاف عقاباً، فانغمس في الرذائل، فهم يتخبّطون لا يعرفون معروفاً ولا ينكرون منكراً. أولئك لهم سوء العذاب في الدنيا بالأسر والقتل، وهم في الآخرة أشد أهل النار خساراً.", "h": ["بيان إعجاز القرآن، إذ آياته مؤلّفة من مثل «طس» و«حم»، وعجز العرب عن تأليف مثله.", "بيان كون القرآن هدى وبشرى للمؤمنين الملتزمين بمتطلّبات الإيمان.", "إنكار البعث والدار الآخرة يجعل صاحبه شر الخليقة."], "k": "«الذين يقيمون الصلاة ويؤتون الزكاة وهم بالآخرة هم يوقنون»… البشرى لها شروط؛ فأيها أحتاج أن أقوّيه في نفسي؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِيمٍ عَلِيمٍ ﴿٦﴾ إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦٓ إِنِّيٓ ءَانَسۡتُ نَارٗا سَـَٔاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِيكُم بِشِهَابٖ قَبَسٖ لَّعَلَّكُمۡ تَصۡطَلُونَ ﴿٧﴾ فَلَمَّا جَآءَهَا نُودِيَ أَنۢ بُورِكَ مَن فِي ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٨﴾ يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٩﴾ وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ ﴿١٠﴾ إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوٓءٖ فَإِنِّي غَفُورٞ رَّحِيمٞ ﴿١١﴾", "w": [["وإنك لتُلقّى القرآن", "تُلقّنه وتحفظه وتعلّمه."], ["من لدن حكيم عليم", "من عند الله جل جلاله."], ["آنست ناراً", "أبصرت ناراً من بعيد حصل لي بها بعض الأنس."], ["سآتيكم منها بخبر", "عن الطريق، إذ ضلّوا طريقهم إلى مصر في الصحراء."], ["بشهاب قبس", "بشعلة نار مقبوسة مأخوذة من أصلها."], ["لعلكم تصطلون", "تستدفئون."], ["أن بورك من في النار", "بارك الله من في النار، وهو موسى ﵇ في البقعة المباركة."], ["تهتزّ كأنها جانّ", "تتحرك بسرعة كأنها حية خفيفة السرعة."], ["ولم يعقّب", "لم يرجع إليها خوفاً وفزعاً منها."], ["ثم بدّل حسناً بعد سوء", "تاب فعمل صالحاً بعد الذي حصل منه من السوء."]], "m": "ما زال السياق في تقرير النبوة المحمدية: وإنك لتُلقّى القرآن وتحفظه من لدن حكيم في تدبيره عليم بخلقه. اذكر للمكذّبين بنبوّتك إذ قال موسى لأهله في ليلة شاتية باردة وقد ضلّوا الطريق: إني أبصرت ناراً، سآتيكم منها بخبر عن الطريق، أو آتيكم بشعلة لعلكم تستدفئون؛ فهل مثل هذا يكون بغير تلقٍّ من الله؟ فلما جاءها نودي: أن بورك من في النار ومن حولها، وهو موسى ﵇ ومن حولها من أرض القدس والشام، والله أعلم بمراده من كلامه، وسبحان الله رب العالمين عما لا يليق بجلاله. يا موسى إنه أنا الله العزيز الحكيم. ثم أمره أن يلقي العصا تمريناً له على استعمالها، فلما رآها تهتزّ كأنها حية ولّى مدبراً ولم يرجع خوفاً، فناداه: يا موسى لا تخف، إني لا يخاف لديّ المرسلون، إلا من ظلم نفسه بذنب، فإن تاب وعمل حسناً بعد السوء فإني غفور رحيم. طمأنه بهذا لأنه كان يشعر بذنب قتل القبطي قبل نبوّته.", "h": ["تقرير النبوة المحمدية.", "مشروعية السفر بالأهل والولد، وجواز خطأ الطريق حتى على الأنبياء والأذكياء.", "قيّومية الرجل على النساء والأطفال.", "تجلّي الرب تعالى لموسى في البقعة المباركة ومناجاته وتدريبه على العصا التي يقاوم بها فرعون وملأه فيما بعد.", "الظلم يسبّب الخوف والعقوبة، إلا من تاب منه وأصلح، فإن الله غفور رحيم."], "k": "«ثم بدّل حسناً بعد سوء»… الباب لم يُغلق؛ فما السوء الذي أبدّله اليوم بحسن؟"}, {"lbl": "الآيات ١٢ – ١٤", "q": "وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿١٢﴾ فَلَمَّا جَآءَتۡهُمۡ ءَايَٰتُنَا مُبۡصِرَةٗ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ ﴿١٣﴾ وَجَحَدُواْ بِهَا وَٱسۡتَيۡقَنَتۡهَآ أَنفُسُهُمۡ ظُلۡمٗا وَعُلُوّٗاۚ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ﴿١٤﴾", "w": [["في جيبك", "جيب ثوبك."], ["من غير سوء", "من غير برص ونحوه، بل هو بياض إشراق."], ["في تسع آيات", "ضمن تسع آيات مرسلاً بها إلى فرعون."], ["مبصرة", "مضيئة واضحة مشرقة."], ["وجحدوا بها", "لم يُقرّوا بها ولم يعترفوا."], ["واستيقنتها أنفسهم", "أيقنوا أنها من عند الله."], ["ظلماً وعلوّاً", "ردّوها لأنهم ظالمون مستكبرون."]], "m": "بعد أن طمأن الله موسى أمره أن يدخل يده في جيب قميصه تخرج بيضاء من غير برص، بياض إشراق يكاد يذهب بالأبصار، ضمن تسع آيات مرسلاً بها إلى فرعون وقومه، إنهم كانوا قوماً خارجين عن الاعتدال إلى الإسراف في الشر والفساد. فلما جاءتهم آياتنا واضحة دالة على صدق موسى رفضوها وقالوا: هذا سحر مبين. وجحدوا بها وكذّبوا، وقد تيقّنتها أنفسهم أنها من عند الله، وإنما حملهم على التكذيب مع العلم ظلمهم واستكبارهم. فانظر يا رسولنا كيف كان عاقبة المفسدين، وهي إهلاكهم.", "h": ["آية اليد إحدى الآيات التسع التي أوتيها موسى ﵇.", "التنديد بالفسق، واستحقاق أهله العذاب في الدارين.", "الكبر والعلوّ في الأرض يجحد صاحبهما الحق ولا يقرّ به وهو يعلم أنه حق.", "عاقبة الفساد في الأرض بالمعاصي سوأى، والعياذ بالله تعالى."], "k": "«وجحدوا بها واستيقنتها أنفسهم»… قد أعرف الحق وأردّه كبراً؛ فهل في نفسي حق أعرفه ولا أعترف به؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (271, 27, 15, 26, 'سورة النمل ١٥ – ٢٦', 'سليمان ﵇ ووادي النمل: «ربّ أوزعني أن أشكر نعمتك»، والهدهد: «أحطت بما لم تحط به»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 271) = $j$[{"lbl": "الآيات ١٥ – ١٩", "q": "وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ وَسُلَيۡمَٰنَ عِلۡمٗاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ ﴿١٥﴾ وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَـٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ ﴿١٦﴾ وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ ﴿١٧﴾ حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَـٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ ﴿١٨﴾ فَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّـٰلِحِينَ ﴿١٩﴾", "w": [["علماً", "علماً لم يكن لغيرهما، كمعرفة لغة الطير، إلى جانب علم الشرع."], ["وقالا الحمد لله", "شكراً له."], ["على كثير من عباده المؤمنين", "بالنبوة وتسخير الجن والإنس والشياطين."], ["وورث سليمان داود", "ورث أباه بعد موته في النبوة والملك والعلم دون باقي أولاده."], ["علّمنا منطق الطير", "فهم أصوات الطير وما تقوله إذا صفرت."], ["وأوتينا من كل شيء", "مما أوتيه غيرنا من الأنبياء والملوك."], ["وحُشر لسليمان", "جُمع له جنوده من الجن والإنس والطير في مسير له."], ["فهم يوزعون", "يُساقون ويُردّ أولهم إلى آخرهم ليسيروا في نظام."], ["لا يحطمنّكم سليمان", "لا يكسرنّكم ويقتلنّكم."], ["أوزعني أن أشكر", "ألهمني ووفّقني لأن أشكر نعمتك."]], "m": "هذا بداية قصص داود وسليمان ﵉، دليلاً آخر على أن الله يعلّم رسوله من لدنه: ولقد آتينا داود وسليمان علماً خاصاً كمعرفة منطق الطير وصنع الدروع، زيادة على علم الشرع والقضاء، وقالا: الحمد لله الذي فضّلنا على كثير من عباده المؤمنين. وورث سليمان داود وحده دون باقي أولاده، في النبوة والعلم والملك، لا في الدرهم والدينار، لأن الأنبياء لا يورثون. وقال: يا أيها الناس علّمنا منطق الطير، وأوتينا من كل شيء، إن هذا لهو الفضل المبين. وجُمع لسليمان جنوده من الجن والإنس والطير في مسير لهم، يُساقون بانتظام لا يتقدّم بعضهم بعضاً، حتى إذا أتوا على وادي النمل قالت نملة: يا أيها النمل ادخلوا مساكنكم لا يحطمنّكم سليمان وجنوده وهم لا يشعرون، قالت ذلك رحمة وشفقة على بنات جنسها، تعلّم البشر النصح لبني جنسهم، واعتذرت لسليمان وجنده بأنهم لا يشعرون. فتبسّم سليمان ضاحكاً من قولها، وقال: رب ألهمني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ، ويسّر لي عملاً صالحاً ترضاه، وأدخلني برحمتك في عبادك الصالحين.", "h": ["وجوب الشكر على النعم.", "وراثة سليمان لداود لم تكن في المال، لأن الأنبياء لا يورثون، وإنما كانت في النبوة والعلم والملك.", "آية تعليم الله تعالى سليمان منطق الطير، وتسخير الجن والشياطين له.", "فضل النمل على كثير من المخلوقات، ظهر في نصح النملة لأخواتها وشفقتها عليهن.", "ذكاء النمل وفطنته مما أضحك سليمان متعجّباً منه.", "تقرير النبوة المحمدية، إذ مثل هذا الحديث لا يتأتّى له إلا بالوحي الإلهي."], "k": "«ربّ أوزعني أن أشكر نعمتك»… في قمة الملك طلب سليمان ﵇ التوفيق للشكر؛ فهل أطلبه أنا في نعمي الصغيرة؟"}, {"lbl": "الآيات ٢٠ – ٢٦", "q": "وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَالِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ ﴿٢٠﴾ لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ﴿٢١﴾ فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ ﴿٢٢﴾ إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ ﴿٢٣﴾ وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ ﴿٢٤﴾ أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ ﴿٢٥﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩ ﴿٢٦﴾", "w": [["وتفقّد الطير", "تعهّدها ونظر فيها."], ["ما لي لا أرى الهدهد", "ما عرض لي فمنعني من رؤيته؟"], ["لأعذّبنّه عذاباً شديداً", "بنتف ريشه وتركه للهوامّ."], ["بسلطان مبين", "بحجة واضحة على عذره في غيبته."], ["فمكث غير بعيد", "قليلاً من الزمن."], ["أحطت بما لم تحط به", "اطّلعت على ما لم تطّلع عليه."], ["من سبأ", "قبيلة من قبائل اليمن."], ["إني وجدت امرأة", "هي بلقيس الملكة."], ["ولها عرش عظيم", "سرير كبير."], ["فصدّهم عن السبيل", "عن طريق الحق والهدى."], ["يُخرج الخبء", "المخبوء في السماوات من الأمطار، وفي الأرض من النبات."]], "m": "تفقّد سليمان جنده من الطير طالباً الهدهد لأمر عرض له وهو يتهيّأ لرحلة، فلم يجده، فقال: ما لي لا أرى الهدهد؟ أم كان من الغائبين؟ لأعذّبنّه عذاباً شديداً، أو لأذبحنّه، أو ليأتينّي بحجة واضحة على سبب غيبته. فمكث زمناً قليلاً وجاء فقال في تواضع: اطّلعت على ما لم تطّلع عليه، وجئتك من سبأ بخبر صادق لا شك فيه: إني وجدت امرأة تملكهم، وأوتيت من كل شيء من أسباب القوة ومظاهر الملك، ولها سرير ملك عظيم. وجدتها وقومها يسجدون للشمس من دون الله، وزيّن لهم الشيطان أعمالهم الشركية فصدّهم عن سبيل الحق، فهم لا يهتدون أن يسجدوا لله الذي يُخرج المخبوء في السماوات والأرض، ويعلم ما تخفون وما تعلنون، الله لا إله إلا هو رب العرش العظيم، ووصفه بالعرش العظيم ليقابل وصف عرشها، وأين عرش مخلوقة من عرش الخالق؟", "h": ["مشروعية استعراض الجيوش وتفقّد أحوال الرعية.", "مشروعية التعزير لمن خالف أمر السلطان بلا عذر شرعي.", "مشروعية اتخاذ طائرات الاستكشاف ودراسة جغرافية العالم.", "تحقيق قول الرسول ﷺ: «لن يفلح قوم ولّوا أمرهم امرأة».", "بيان أن هناك من كانوا يعبدون الشمس، إذ سجودهم لها عبادة.", "بيان أن الأحق بالعبادة الله الذي لا إله إلا هو رب العرش العظيم.", "مشروعية السجود لمن تلا هذه الآية أو استمع إلى تلاوتها."], "k": "«وتفقّد الطير»… ملك عظيم يلاحظ غياب طائر صغير؛ فمن غاب عني ولم ألحظ غيابه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 271;
insert into public.tdb_cards(topic, i, body) select 271, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥ – ١٩", "q": "وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ وَسُلَيۡمَٰنَ عِلۡمٗاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ ﴿١٥﴾ وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَـٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ ﴿١٦﴾ وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ ﴿١٧﴾ حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَـٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ ﴿١٨﴾ فَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّـٰلِحِينَ ﴿١٩﴾", "w": [["علماً", "علماً لم يكن لغيرهما، كمعرفة لغة الطير، إلى جانب علم الشرع."], ["وقالا الحمد لله", "شكراً له."], ["على كثير من عباده المؤمنين", "بالنبوة وتسخير الجن والإنس والشياطين."], ["وورث سليمان داود", "ورث أباه بعد موته في النبوة والملك والعلم دون باقي أولاده."], ["علّمنا منطق الطير", "فهم أصوات الطير وما تقوله إذا صفرت."], ["وأوتينا من كل شيء", "مما أوتيه غيرنا من الأنبياء والملوك."], ["وحُشر لسليمان", "جُمع له جنوده من الجن والإنس والطير في مسير له."], ["فهم يوزعون", "يُساقون ويُردّ أولهم إلى آخرهم ليسيروا في نظام."], ["لا يحطمنّكم سليمان", "لا يكسرنّكم ويقتلنّكم."], ["أوزعني أن أشكر", "ألهمني ووفّقني لأن أشكر نعمتك."]], "m": "هذا بداية قصص داود وسليمان ﵉، دليلاً آخر على أن الله يعلّم رسوله من لدنه: ولقد آتينا داود وسليمان علماً خاصاً كمعرفة منطق الطير وصنع الدروع، زيادة على علم الشرع والقضاء، وقالا: الحمد لله الذي فضّلنا على كثير من عباده المؤمنين. وورث سليمان داود وحده دون باقي أولاده، في النبوة والعلم والملك، لا في الدرهم والدينار، لأن الأنبياء لا يورثون. وقال: يا أيها الناس علّمنا منطق الطير، وأوتينا من كل شيء، إن هذا لهو الفضل المبين. وجُمع لسليمان جنوده من الجن والإنس والطير في مسير لهم، يُساقون بانتظام لا يتقدّم بعضهم بعضاً، حتى إذا أتوا على وادي النمل قالت نملة: يا أيها النمل ادخلوا مساكنكم لا يحطمنّكم سليمان وجنوده وهم لا يشعرون، قالت ذلك رحمة وشفقة على بنات جنسها، تعلّم البشر النصح لبني جنسهم، واعتذرت لسليمان وجنده بأنهم لا يشعرون. فتبسّم سليمان ضاحكاً من قولها، وقال: رب ألهمني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ، ويسّر لي عملاً صالحاً ترضاه، وأدخلني برحمتك في عبادك الصالحين.", "h": ["وجوب الشكر على النعم.", "وراثة سليمان لداود لم تكن في المال، لأن الأنبياء لا يورثون، وإنما كانت في النبوة والعلم والملك.", "آية تعليم الله تعالى سليمان منطق الطير، وتسخير الجن والشياطين له.", "فضل النمل على كثير من المخلوقات، ظهر في نصح النملة لأخواتها وشفقتها عليهن.", "ذكاء النمل وفطنته مما أضحك سليمان متعجّباً منه.", "تقرير النبوة المحمدية، إذ مثل هذا الحديث لا يتأتّى له إلا بالوحي الإلهي."], "k": "«ربّ أوزعني أن أشكر نعمتك»… في قمة الملك طلب سليمان ﵇ التوفيق للشكر؛ فهل أطلبه أنا في نعمي الصغيرة؟"}, {"lbl": "الآيات ٢٠ – ٢٦", "q": "وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَالِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ ﴿٢٠﴾ لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ﴿٢١﴾ فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ ﴿٢٢﴾ إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ ﴿٢٣﴾ وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ ﴿٢٤﴾ أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ ﴿٢٥﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩ ﴿٢٦﴾", "w": [["وتفقّد الطير", "تعهّدها ونظر فيها."], ["ما لي لا أرى الهدهد", "ما عرض لي فمنعني من رؤيته؟"], ["لأعذّبنّه عذاباً شديداً", "بنتف ريشه وتركه للهوامّ."], ["بسلطان مبين", "بحجة واضحة على عذره في غيبته."], ["فمكث غير بعيد", "قليلاً من الزمن."], ["أحطت بما لم تحط به", "اطّلعت على ما لم تطّلع عليه."], ["من سبأ", "قبيلة من قبائل اليمن."], ["إني وجدت امرأة", "هي بلقيس الملكة."], ["ولها عرش عظيم", "سرير كبير."], ["فصدّهم عن السبيل", "عن طريق الحق والهدى."], ["يُخرج الخبء", "المخبوء في السماوات من الأمطار، وفي الأرض من النبات."]], "m": "تفقّد سليمان جنده من الطير طالباً الهدهد لأمر عرض له وهو يتهيّأ لرحلة، فلم يجده، فقال: ما لي لا أرى الهدهد؟ أم كان من الغائبين؟ لأعذّبنّه عذاباً شديداً، أو لأذبحنّه، أو ليأتينّي بحجة واضحة على سبب غيبته. فمكث زمناً قليلاً وجاء فقال في تواضع: اطّلعت على ما لم تطّلع عليه، وجئتك من سبأ بخبر صادق لا شك فيه: إني وجدت امرأة تملكهم، وأوتيت من كل شيء من أسباب القوة ومظاهر الملك، ولها سرير ملك عظيم. وجدتها وقومها يسجدون للشمس من دون الله، وزيّن لهم الشيطان أعمالهم الشركية فصدّهم عن سبيل الحق، فهم لا يهتدون أن يسجدوا لله الذي يُخرج المخبوء في السماوات والأرض، ويعلم ما تخفون وما تعلنون، الله لا إله إلا هو رب العرش العظيم، ووصفه بالعرش العظيم ليقابل وصف عرشها، وأين عرش مخلوقة من عرش الخالق؟", "h": ["مشروعية استعراض الجيوش وتفقّد أحوال الرعية.", "مشروعية التعزير لمن خالف أمر السلطان بلا عذر شرعي.", "مشروعية اتخاذ طائرات الاستكشاف ودراسة جغرافية العالم.", "تحقيق قول الرسول ﷺ: «لن يفلح قوم ولّوا أمرهم امرأة».", "بيان أن هناك من كانوا يعبدون الشمس، إذ سجودهم لها عبادة.", "بيان أن الأحق بالعبادة الله الذي لا إله إلا هو رب العرش العظيم.", "مشروعية السجود لمن تلا هذه الآية أو استمع إلى تلاوتها."], "k": "«وتفقّد الطير»… ملك عظيم يلاحظ غياب طائر صغير؛ فمن غاب عني ولم ألحظ غيابه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (272, 27, 27, 40, 'سورة النمل ٢٧ – ٤٠', 'سليمان ﵇ وملكة سبأ: «إنه من سليمان وإنه بسم الله الرحمن الرحيم»، و«هذا من فضل ربي ليبلوني أأشكر أم أكفر»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 272) = $j$[{"lbl": "الآيات ٢٧ – ٣١", "q": "۞قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ ﴿٢٧﴾ ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ ﴿٢٨﴾ قَالَتۡ يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبٞ كَرِيمٌ ﴿٢٩﴾ إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ﴿٣٠﴾ أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ ﴿٣١﴾", "w": [["سننظر أصدقت", "بعد اختبارنا لك."], ["فألقه إليهم", "إلى رجال القصر وهم في مجلس الحكم."], ["ثم تولّ عنهم", "تنحَّ جانباً متوارياً عنهم."], ["فانظر ماذا يرجعون", "ماذا يقول بعضهم لبعض في شأن الكتاب."], ["يا أيها الملأ", "يا أشراف البلاد وأعيانها وأهل الحل والعقد."], ["ألقي إليّ كتاب كريم", "ألقاه الهدهد في حجرها."], ["ألا تعلوا عليّ", "لا تتكبّروا انقياداً للنفس والهوى."], ["وأتوني مسلمين", "منقادين خاضعين."]], "m": "قال سليمان للهدهد: سننظر باختبارنا لك أصدقت فيما ادّعيت أم كنت من الكاذبين. فكتب كتاباً وختمه، وقال له: اذهب بكتابي هذا فألقه إليهم، ثم تنحَّ جانباً مختفياً، فانظر ماذا يقول بعضهم لبعض في شأنه. فذهب الهدهد ودخل القصر من كوّة فألقى الكتاب في حجر الملكة، فارتاعت له وقرأته، ثم قالت لأشراف قومها: يا أيها الملأ إني ألقي إليّ كتاب كريم، وصفته بالكرم لما حواه من عبارات كريمة ولأنه مختوم. إنه من سليمان، وإنه مكتوب باسم الله الرحمن الرحيم، أي بإذنه وشرعه، ومضمونه: ألا تتكبّروا على الحق، وأتوني منقادين خاضعين.", "h": ["مشروعية الاختبار وإجراء التحقيق مع المتهم.", "مشروعية استخدام السلطان أفراد رعيته لكفاية المستخدَم.", "مشروعية إرسال العيون للتعرّف على أحوال العدو وما يدور عنده.", "مشروعية كتابة «بسم الله الرحمن الرحيم» في الرسائل والكتب ذات البال، لدلالتها على توحيد الله تعالى وأنه رحمن رحيم."], "k": "«إنه من سليمان وإنه بسم الله الرحمن الرحيم»… يبدأ الملك رسالته باسم الله؛ فبمَ أبدأ رسائلي وأعمالي؟"}, {"lbl": "الآيات ٣٢ – ٣٥", "q": "قَالَتۡ يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ ﴿٣٢﴾ قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ ﴿٣٣﴾ قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةٗۚ وَكَذَٰلِكَ يَفۡعَلُونَ ﴿٣٤﴾ وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ﴿٣٥﴾", "w": [["أفتوني في أمري", "بيّنوا لي وجه الصواب فيه."], ["ما كنت قاطعة أمراً", "قاضيته."], ["حتى تشهدون", "تحضروني وتُبدوا رأيكم فيه."], ["أولو بأس شديد", "أصحاب قوة مادية وبأس شديد في الحروب."], ["إذا دخلوا قرية", "مدينة وعاصمة ملك."], ["أفسدوها", "خرّبوها إذا دخلوها عنوة بلا مصالحة."], ["وكذلك يفعلون", "وكالذي ذكرت لكم يفعل مرسلو هذا الكتاب."]], "m": "قالت الملكة لرجال دولتها: يا أيها الملأ أشيروا عليّ في أمري، ما كنت قاضية فيه حتى تحضروني وتُبدوا رأيكم. قالوا: نحن أولو قوة عسكرية من سلاح وعتاد، وأولو بأس شديد عند خوض المعارك، والأمر إليك فانظري ماذا تأمرين فننفّذ. قالت: إن الملوك إذا دخلوا مدينة عنوة بلا صلح خرّبوا معالمها، وجعلوا أعزّة أهلها أذلّة بإهانتهم وخلعهم من مناصبهم، وكذلك يفعل أصحاب هذا الكتاب، وإني مرسلة إليهم بهدية فناظرة بمَ يرجع المرسلون: فإن قبلوها فهم أصحاب دنيا، وإن رفضوها فهم أصحاب دين، وعلى ضوء ذلك نتصرّف.", "h": ["تقرير مبدأ الشورى في الحكم.", "مشروعية إبداء الرأي بصدق ونزاهة، ثم ترك الأمر لأهله.", "مشروعية إعداد العدّة وتوفير السلاح وتدريب الرجال على حمله واستعماله.", "دخول العدو المحارب الغالب البلاد عنوة ذو خطورة، فلذا يُتلافى الأمر بالمصالحة.", "بيان حسن سياسة الملكة بلقيس وفطنتها وذكائها."], "k": "«ما كنت قاطعة أمراً حتى تشهدون»… ملكة تستشير قومها؛ فهل أشاور من حولي قبل أن أقطع في أمورهم؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ ﴿٣٦﴾ ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم بِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةٗ وَهُمۡ صَٰغِرُونَ ﴿٣٧﴾ قَالَ يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ ﴿٣٨﴾ قَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ ﴿٣٩﴾ قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ ﴿٤٠﴾", "w": [["فلما جاء سليمان", "رسول الملكة يحمل الهدية ومعه أتباعه."], ["فما آتاني الله خير مما آتاكم", "أعطاني النبوة والملك، وذلك خير مما أعطاكم من المال."], ["بهديتكم تفرحون", "لحبّكم الدنيا ورغبتكم في زخارفها."], ["بجنود لا قِبل لهم بها", "لا طاقة لهم بقتالها."], ["وهم صاغرون", "ذليلون إن لم يأتوني منقادين."], ["قال عفريت من الجن", "جنّي قوي شديد."], ["قبل أن تقوم من مقامك", "من مجلس قضائك، وهو من الصبح إلى الظهر."], ["وإني عليه لقوي أمين", "قوي على حمله، أمين على ما فيه من الجواهر."], ["قال الذي عنده علم من الكتاب", "سليمان ﵇."]], "m": "بعثت الملكة بهديتها تختبر سليمان: أهو رجل دنيا أم رجل دين؟ فلما جاء رسولها قال سليمان: أتمدّونني بمال؟ فما آتاني الله من النبوة والعلم والملك خير مما آتاكم من المال، بل أنتم بهديتكم تفرحون لحبّكم الدنيا. ارجع إليهم بهديتك، فلنأتينّهم بجنود لا طاقة لهم بها، ولنخرجنّهم منها أذلّة وهم صاغرون إن لم يأتوا مسلمين. ثم قال لأشراف دولته: أيكم يأتيني بعرشها قبل أن يأتوني مسلمين؟ قال عفريت من الجن: أنا آتيك به قبل أن تقوم من مجلس قضائك، وإني عليه لقوي أمين. قال الذي عنده علم من الكتاب، وهو سليمان: أنا آتيك به قبل أن يرتدّ إليك طرفك، وسأل ربه باسمه الأعظم، فإذا العرش بين يديه. فلما رآه مستقرّاً قال: هذا من فضل ربي، لم يكن لي به يد، ليبلوني أأشكر نعمته أم أكفرها، ومن شكر فإنما يعود نفع شكره عليه، ومن كفر فإن ربي غني عن شكره، كريم قد لا يسلب النعمة من الكافر بها.", "h": ["أهل الآخرة لا يفرحون بالدنيا، وأهل الدنيا لا يفرحون بالآخرة.", "استعمال أسلوب التخويف مع القدرة على إنفاذه أليق مع العدو.", "تقرير أن سليمان كان يستخدم الجن، وأنهم يخدمونه في أصعب الأمور.", "استجابة الله تعالى لسليمان، فأحضر له العرش من اليمن إلى الشام قبل ارتداد طرف الناظر.", "وجوب ردّ الفضل إلى أهله، فسليمان قال: «هذا من فضل ربي».", "وجوب الشكر، وعائدته تعود على الشاكر، ولكرم الله تعالى قد لا يسلب النعمة فور عدم شكرها لحلمه."], "k": "«هذا من فضل ربي ليبلوني أأشكر أم أكفر»… كل نجاح عندي امتحان؛ فهل أنسبه لنفسي أم لربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 272;
insert into public.tdb_cards(topic, i, body) select 272, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧ – ٣١", "q": "۞قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ ﴿٢٧﴾ ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ ﴿٢٨﴾ قَالَتۡ يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبٞ كَرِيمٌ ﴿٢٩﴾ إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ﴿٣٠﴾ أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ ﴿٣١﴾", "w": [["سننظر أصدقت", "بعد اختبارنا لك."], ["فألقه إليهم", "إلى رجال القصر وهم في مجلس الحكم."], ["ثم تولّ عنهم", "تنحَّ جانباً متوارياً عنهم."], ["فانظر ماذا يرجعون", "ماذا يقول بعضهم لبعض في شأن الكتاب."], ["يا أيها الملأ", "يا أشراف البلاد وأعيانها وأهل الحل والعقد."], ["ألقي إليّ كتاب كريم", "ألقاه الهدهد في حجرها."], ["ألا تعلوا عليّ", "لا تتكبّروا انقياداً للنفس والهوى."], ["وأتوني مسلمين", "منقادين خاضعين."]], "m": "قال سليمان للهدهد: سننظر باختبارنا لك أصدقت فيما ادّعيت أم كنت من الكاذبين. فكتب كتاباً وختمه، وقال له: اذهب بكتابي هذا فألقه إليهم، ثم تنحَّ جانباً مختفياً، فانظر ماذا يقول بعضهم لبعض في شأنه. فذهب الهدهد ودخل القصر من كوّة فألقى الكتاب في حجر الملكة، فارتاعت له وقرأته، ثم قالت لأشراف قومها: يا أيها الملأ إني ألقي إليّ كتاب كريم، وصفته بالكرم لما حواه من عبارات كريمة ولأنه مختوم. إنه من سليمان، وإنه مكتوب باسم الله الرحمن الرحيم، أي بإذنه وشرعه، ومضمونه: ألا تتكبّروا على الحق، وأتوني منقادين خاضعين.", "h": ["مشروعية الاختبار وإجراء التحقيق مع المتهم.", "مشروعية استخدام السلطان أفراد رعيته لكفاية المستخدَم.", "مشروعية إرسال العيون للتعرّف على أحوال العدو وما يدور عنده.", "مشروعية كتابة «بسم الله الرحمن الرحيم» في الرسائل والكتب ذات البال، لدلالتها على توحيد الله تعالى وأنه رحمن رحيم."], "k": "«إنه من سليمان وإنه بسم الله الرحمن الرحيم»… يبدأ الملك رسالته باسم الله؛ فبمَ أبدأ رسائلي وأعمالي؟"}, {"lbl": "الآيات ٣٢ – ٣٥", "q": "قَالَتۡ يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ ﴿٣٢﴾ قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ ﴿٣٣﴾ قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةٗۚ وَكَذَٰلِكَ يَفۡعَلُونَ ﴿٣٤﴾ وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ﴿٣٥﴾", "w": [["أفتوني في أمري", "بيّنوا لي وجه الصواب فيه."], ["ما كنت قاطعة أمراً", "قاضيته."], ["حتى تشهدون", "تحضروني وتُبدوا رأيكم فيه."], ["أولو بأس شديد", "أصحاب قوة مادية وبأس شديد في الحروب."], ["إذا دخلوا قرية", "مدينة وعاصمة ملك."], ["أفسدوها", "خرّبوها إذا دخلوها عنوة بلا مصالحة."], ["وكذلك يفعلون", "وكالذي ذكرت لكم يفعل مرسلو هذا الكتاب."]], "m": "قالت الملكة لرجال دولتها: يا أيها الملأ أشيروا عليّ في أمري، ما كنت قاضية فيه حتى تحضروني وتُبدوا رأيكم. قالوا: نحن أولو قوة عسكرية من سلاح وعتاد، وأولو بأس شديد عند خوض المعارك، والأمر إليك فانظري ماذا تأمرين فننفّذ. قالت: إن الملوك إذا دخلوا مدينة عنوة بلا صلح خرّبوا معالمها، وجعلوا أعزّة أهلها أذلّة بإهانتهم وخلعهم من مناصبهم، وكذلك يفعل أصحاب هذا الكتاب، وإني مرسلة إليهم بهدية فناظرة بمَ يرجع المرسلون: فإن قبلوها فهم أصحاب دنيا، وإن رفضوها فهم أصحاب دين، وعلى ضوء ذلك نتصرّف.", "h": ["تقرير مبدأ الشورى في الحكم.", "مشروعية إبداء الرأي بصدق ونزاهة، ثم ترك الأمر لأهله.", "مشروعية إعداد العدّة وتوفير السلاح وتدريب الرجال على حمله واستعماله.", "دخول العدو المحارب الغالب البلاد عنوة ذو خطورة، فلذا يُتلافى الأمر بالمصالحة.", "بيان حسن سياسة الملكة بلقيس وفطنتها وذكائها."], "k": "«ما كنت قاطعة أمراً حتى تشهدون»… ملكة تستشير قومها؛ فهل أشاور من حولي قبل أن أقطع في أمورهم؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ ﴿٣٦﴾ ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم بِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةٗ وَهُمۡ صَٰغِرُونَ ﴿٣٧﴾ قَالَ يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ ﴿٣٨﴾ قَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ ﴿٣٩﴾ قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ ﴿٤٠﴾", "w": [["فلما جاء سليمان", "رسول الملكة يحمل الهدية ومعه أتباعه."], ["فما آتاني الله خير مما آتاكم", "أعطاني النبوة والملك، وذلك خير مما أعطاكم من المال."], ["بهديتكم تفرحون", "لحبّكم الدنيا ورغبتكم في زخارفها."], ["بجنود لا قِبل لهم بها", "لا طاقة لهم بقتالها."], ["وهم صاغرون", "ذليلون إن لم يأتوني منقادين."], ["قال عفريت من الجن", "جنّي قوي شديد."], ["قبل أن تقوم من مقامك", "من مجلس قضائك، وهو من الصبح إلى الظهر."], ["وإني عليه لقوي أمين", "قوي على حمله، أمين على ما فيه من الجواهر."], ["قال الذي عنده علم من الكتاب", "سليمان ﵇."]], "m": "بعثت الملكة بهديتها تختبر سليمان: أهو رجل دنيا أم رجل دين؟ فلما جاء رسولها قال سليمان: أتمدّونني بمال؟ فما آتاني الله من النبوة والعلم والملك خير مما آتاكم من المال، بل أنتم بهديتكم تفرحون لحبّكم الدنيا. ارجع إليهم بهديتك، فلنأتينّهم بجنود لا طاقة لهم بها، ولنخرجنّهم منها أذلّة وهم صاغرون إن لم يأتوا مسلمين. ثم قال لأشراف دولته: أيكم يأتيني بعرشها قبل أن يأتوني مسلمين؟ قال عفريت من الجن: أنا آتيك به قبل أن تقوم من مجلس قضائك، وإني عليه لقوي أمين. قال الذي عنده علم من الكتاب، وهو سليمان: أنا آتيك به قبل أن يرتدّ إليك طرفك، وسأل ربه باسمه الأعظم، فإذا العرش بين يديه. فلما رآه مستقرّاً قال: هذا من فضل ربي، لم يكن لي به يد، ليبلوني أأشكر نعمته أم أكفرها، ومن شكر فإنما يعود نفع شكره عليه، ومن كفر فإن ربي غني عن شكره، كريم قد لا يسلب النعمة من الكافر بها.", "h": ["أهل الآخرة لا يفرحون بالدنيا، وأهل الدنيا لا يفرحون بالآخرة.", "استعمال أسلوب التخويف مع القدرة على إنفاذه أليق مع العدو.", "تقرير أن سليمان كان يستخدم الجن، وأنهم يخدمونه في أصعب الأمور.", "استجابة الله تعالى لسليمان، فأحضر له العرش من اليمن إلى الشام قبل ارتداد طرف الناظر.", "وجوب ردّ الفضل إلى أهله، فسليمان قال: «هذا من فضل ربي».", "وجوب الشكر، وعائدته تعود على الشاكر، ولكرم الله تعالى قد لا يسلب النعمة فور عدم شكرها لحلمه."], "k": "«هذا من فضل ربي ليبلوني أأشكر أم أكفر»… كل نجاح عندي امتحان؛ فهل أنسبه لنفسي أم لربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (273, 27, 41, 55, 'سورة النمل ٤١ – ٥٥', 'بلقيس: «وأسلمت مع سليمان لله رب العالمين»، وثمود: «تسعة رهط يفسدون في الأرض»، ولوط: «أتأتون الفاحشة وأنتم تبصرون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 273) = $j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "قَالَ نَكِّرُواْ لَهَا عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِيٓ أَمۡ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهۡتَدُونَ ﴿٤١﴾ فَلَمَّا جَآءَتۡ قِيلَ أَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِينَ ﴿٤٢﴾ وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمٖ كَٰفِرِينَ ﴿٤٣﴾ قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةٗ وَكَشَفَتۡ عَن سَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحٞ مُّمَرَّدٞ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٤٤﴾", "w": [["نكّروا لها عرشها", "غيّروا هيئته وشكله حتى لا يُعرف إلا بصعوبة."], ["أتهتدي", "إلى معرفته."], ["أهكذا عرشك", "شبّهوا عليها، إذ لو قالوا: هذا عرشك، لقالت: نعم."], ["قالت كأنه هو", "فشبّهت عليهم كما شبّهوا."], ["وصدّها ما كانت تعبد", "صرفها عن عبادة الله مع علمها وذكائها ما كانت تعبد من دونه."], ["ادخلي الصرح", "بهو القصر العالي، وفيه بركة ماء مغطّاة بسقف زجاجي."], ["حسبته لجّة", "ماءً غمراً."], ["وكشفت عن ساقيها", "ظانّة أنها تدخل ماءً فرفعت ثيابها."], ["صرح ممرّد من قوارير", "مملّس من زجاج."]], "m": "خرجت بلقيس في موكبها الملكي بعد أن احتاطت لعرشها، إلا أن العرش وصل قبلها. فأراد سليمان أن يختبر عقلها، فأمر رجاله أن يغيّروا عرشها بزيادة ونقص: ننظر أتهتدي إلى معرفته أم تكون من الذين لا يهتدون. فلما جاءت قيل لها: أهكذا عرشك؟ فقالت: كأنه هو، إذ لو قالت: هو، لقيل كيف والمسافة شهران، ولو قالت: ليس هو، لقيل كيف تجهلين سريرك، فكانت ذات ذكاء ودهاء. فأُعجب سليمان بذكائها وقال: وأوتينا العلم من قبلها وكنا مسلمين. وإنما صدّها عن الإيمان ما كانت تعبد من الشمس اتّباعاً لقومها الكافرين. وقيل لها: ادخلي الصرح، وكان بهوه فوق بركة ماء عظيمة سقفها زجاج مملّس، فلما رأته حسبته ماءً فكشفت عن ساقيها، فقال سليمان: إنه صرح مملّس من زجاج. فلما بهرها الموقف وعرفت أنها كانت ضالّة قالت: رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين. ولم يذكر القرآن عنها بعدُ شيئاً، فلنسكت عما سكت عنه القرآن.", "h": ["جواز اختبار الأفراد إذا أريد إسناد أمر لهم لمعرفة قدرتهم العقلية والبدنية.", "بيان حصافة عقل بلقيس، ولذا أسلمت، وظهر ذلك في قولها: «كأنه هو».", "مضارّ التقليد، وما يترتّب عليه من التنكّر للعقل والمنطق.", "حرمة كشف المرأة ساقيها حتى ولو كانت كافرة، فكيف إذا كانت مسلمة.", "فضيلة الائتساء بالصالحين، كما ائتست بلقيس بسليمان في قولها: «وأسلمت مع سليمان لله رب العالمين»."], "k": "«وصدّها ما كانت تعبد من دون الله»… ذكاؤها لم يكفِ وحده حتى تركت ما ألِفته؛ فما الذي ألِفته ويصدّني عن الحق؟"}, {"lbl": "الآيات ٤٥ – ٤٩", "q": "وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحًا أَنِ ٱعۡبُدُواْ ٱللَّهَ فَإِذَا هُمۡ فَرِيقَانِ يَخۡتَصِمُونَ ﴿٤٥﴾ قَالَ يَٰقَوۡمِ لِمَ تَسۡتَعۡجِلُونَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِۖ لَوۡلَا تَسۡتَغۡفِرُونَ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٤٦﴾ قَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَـٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ﴿٤٧﴾ وَكَانَ فِي ٱلۡمَدِينَةِ تِسۡعَةُ رَهۡطٖ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ ﴿٤٨﴾ قَالُواْ تَقَاسَمُواْ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَٰدِقُونَ ﴿٤٩﴾", "w": [["أن اعبدوا الله", "بأن اعبدوا الله."], ["فريقان يختصمون", "طائفتان: مؤمنة موحّدة، وكافرة مشركة."], ["تستعجلون بالسيئة", "تطالبون بالعذاب قبل الرحمة."], ["لولا تستغفرون الله", "هلّا تطلبون المغفرة من ربكم بتوبتكم إليه."], ["اطّيّرنا بك", "تشاءمنا بك وبمن معك من المؤمنين."], ["طائركم عند الله", "ما يصيبكم من المكاره عند الله علمه."], ["بل أنتم قوم تُفتنون", "تُختبرون بالخير والشر."], ["تسعة رهط", "تسعة رجال ظلمة."], ["تقاسموا بالله", "تحالفوا بالله."], ["لنبيّتنّه وأهله", "لنقتلنّه والمؤمنين به ليلاً."], ["ما شهدنا مهلك أهله", "ما حضرنا قتله ولا قتل أهله."]], "m": "هذا بداية قصص صالح ﵇ مع ثمود، وضعاً لقريش أمام أحداث تمثّل حالهم مع نبيّهم: ولقد أرسلنا إلى ثمود أخاهم في النسب صالحاً أن اعبدوا الله وحده، فإذا هم فريقان: موحّدون ومشركون يختصمون. وطالبوه بالعذاب الذي يعدهم، فقال: يا قوم لمَ تستعجلون بالعذاب قبل الرحمة؟ هلّا تستغفرون الله بترك الشرك والمعاصي لعلكم ترحمون. قالوا: تشاءمنا بك وبمن معك. قال: ما يصيبكم من المكاره عند الله علمه وهو كائن لا محالة، وليست القضية تشاؤماً ولا تيامناً، بل أنتم قوم تُختبرون. وكان في مدينة الحِجر تسعة رجال يفسدون في الأرض بالكفر والمعاصي ولا يصلحون، وهم الذين تمالؤوا على عقر الناقة، قالوا في اجتماع خاص: ليحلف كل منكم بالله لنأتينّ صالحاً وأتباعه ليلاً فنقتلهم، ثم نقول لوليّ دمه: ما حضرنا مهلكه ولا مهلك أهله، وإنا لصادقون.", "h": ["تقرير نبوة النبي ﷺ.", "تقرير حقيقة أن الصراع بين الحق والباطل لا ينتهي إلا بانتهاء الباطل.", "حرمة التشاؤم والتيامن كذلك، ولم يُجز الشارع إلا التفاؤل.", "العمل بمعاصي الله تعالى هو الفساد في الأرض، والعمل بطاعته هو الإصلاح.", "تقرير أن المشركين يؤمنون بالله ولذا يحلفون به، ولم يُدخلهم ذلك في الإسلام لشركهم في عبادته غيره."], "k": "«لولا تستغفرون الله لعلكم تُرحمون»… بين يديّ طريق للرحمة أقصر من كل جدال؛ فهل أستغفر الآن؟"}, {"lbl": "الآيات ٥٠ – ٥٣", "q": "وَمَكَرُواْ مَكۡرٗا وَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ ﴿٥٠﴾ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِينَ ﴿٥١﴾ فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ﴿٥٢﴾ وَأَنجَيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿٥٣﴾", "w": [["ومكروا مكراً", "دبّروا طريقة خفية لقتل صالح والمؤمنين."], ["ومكرنا مكراً", "دبّرنا طريقة خفية لنجاة صالح والمؤمنين وإهلاك الظالمين."], ["وهم لا يشعرون", "بأنّا ندبّر لهم طريق هلاكهم."], ["بيوتهم خاوية", "فارغة ليس فيها أحد."], ["بما ظلموا", "بسبب ظلمهم، وهو الشرك والمعاصي."], ["لآية", "لعبرة."], ["وأنجينا الذين آمنوا", "صالحاً والمؤمنين."]], "m": "هذا نهاية قصص صالح مع ثمود: تقاسم التسعة على قتل صالح والمؤمنين ليلاً، ليحولوا في نظرهم دون العذاب الذي واعدهم به بعد ثلاثة أيام، فأتوا صالحاً وهو يصلي في مسجد له تحت الجبل، فسقطت عليهم صخرة من الجبل فأهلكتهم أجمعين، وهكذا مكر الله بهم وهم لا يشعرون، ثم أهلك القوم كلهم بالصيحة فأصبحوا في ديارهم جاثمين. فانظر يا رسولنا كيف كان عاقبة مكرهم: أنّا دمّرناهم وقومهم أجمعين، فتلك بيوتهم خاوية بسبب ظلمهم أنفسهم بالشرك وظلمهم صالحاً والمؤمنين، إن في ذلك لعلامة على قدرة الله وحسن تدبيره لقوم يعلمون. وأنجينا صالحاً والمؤمنين الذين آمنوا وكانوا طوال حياتهم يتّقون عقاب الله بطاعته وطاعة رسوله.", "h": ["تقرير قاعدة: «ولا يحيق المكر السيّئ إلا بأهله».", "تقرير أن ديار الظالمين مآلها الخراب، فالظلم يذر الديار بلاقع.", "الإيمان والتقوى هما سبب النجاة، لأن ولاية الله للعبد تتم بهما."], "k": "«فتلك بيوتهم خاوية بما ظلموا»… أمرّ على بيوت كانت عامرة؛ فهل أعمر بيتي بما يبقيه؟"}, {"lbl": "الآيتان ٥٤ – ٥٥", "q": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ ﴿٥٤﴾ أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ تَجۡهَلُونَ ﴿٥٥﴾", "w": [["ولوطاً", "واذكر لقومك لوطاً إذ قال لقومه."], ["لقومه", "سكان مدن عمورية وسدوم."], ["الفاحشة", "الخصلة القبيحة الشديدة القبح، وهي اللواط."], ["وأنتم تبصرون", "إذ كانوا يأتونها في أنديتهم عياناً بلا ستر."], ["قوم تجهلون", "تجهلون قبح ما تأتون وما يترتّب عليه من خزي وعذاب."]], "m": "هذا بداية قصص لوط ﵇: واذكر كما ذكرت صالحاً لوطاً إذ قال لقومه منكراً موبّخاً: أتأتون الفاحشة وأنتم تبصرون قبحها ببصائركم وأبصاركم، إذ كانوا يأتونها علناً؟ أئنّكم لتأتون الرجال شهوة من دون النساء، لا للعفّة ولا للولد، بل لقضاء الشهوة البهيمية، وفي الوقت نفسه آذيتم نساءكم فهضمتم حقوقهن؟ بل أنتم قوم تجهلون ما يجب عليكم لربكم من الإيمان والطاعة، وما يترتّب على العصيان من العقاب.", "h": ["بيان ما كان عليه قوم لوط من الفساد والهبوط العقلي والخلقي.", "تحريم فاحشة اللواط، وأنها أقبح شيء، وأن فاعلها أحطّ من البهائم.", "الجهل بالله تعالى وما يجب له من الطاعة هو سبب كل شر وفساد في الأرض، ولذا كان الطريق إلى إصلاح البشر تعريفهم بالله تعالى، حتى إذا عرفوه وآمنوا به أمكنهم أن يستقيموا على منهج الإصلاح."], "k": "«بل أنتم قوم تجهلون»… أصل الفساد جهل بالله؛ فكم أعرف ربي معرفةً تمنعني من معصيته؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 273;
insert into public.tdb_cards(topic, i, body) select 273, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "قَالَ نَكِّرُواْ لَهَا عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِيٓ أَمۡ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهۡتَدُونَ ﴿٤١﴾ فَلَمَّا جَآءَتۡ قِيلَ أَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِينَ ﴿٤٢﴾ وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمٖ كَٰفِرِينَ ﴿٤٣﴾ قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةٗ وَكَشَفَتۡ عَن سَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحٞ مُّمَرَّدٞ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٤٤﴾", "w": [["نكّروا لها عرشها", "غيّروا هيئته وشكله حتى لا يُعرف إلا بصعوبة."], ["أتهتدي", "إلى معرفته."], ["أهكذا عرشك", "شبّهوا عليها، إذ لو قالوا: هذا عرشك، لقالت: نعم."], ["قالت كأنه هو", "فشبّهت عليهم كما شبّهوا."], ["وصدّها ما كانت تعبد", "صرفها عن عبادة الله مع علمها وذكائها ما كانت تعبد من دونه."], ["ادخلي الصرح", "بهو القصر العالي، وفيه بركة ماء مغطّاة بسقف زجاجي."], ["حسبته لجّة", "ماءً غمراً."], ["وكشفت عن ساقيها", "ظانّة أنها تدخل ماءً فرفعت ثيابها."], ["صرح ممرّد من قوارير", "مملّس من زجاج."]], "m": "خرجت بلقيس في موكبها الملكي بعد أن احتاطت لعرشها، إلا أن العرش وصل قبلها. فأراد سليمان أن يختبر عقلها، فأمر رجاله أن يغيّروا عرشها بزيادة ونقص: ننظر أتهتدي إلى معرفته أم تكون من الذين لا يهتدون. فلما جاءت قيل لها: أهكذا عرشك؟ فقالت: كأنه هو، إذ لو قالت: هو، لقيل كيف والمسافة شهران، ولو قالت: ليس هو، لقيل كيف تجهلين سريرك، فكانت ذات ذكاء ودهاء. فأُعجب سليمان بذكائها وقال: وأوتينا العلم من قبلها وكنا مسلمين. وإنما صدّها عن الإيمان ما كانت تعبد من الشمس اتّباعاً لقومها الكافرين. وقيل لها: ادخلي الصرح، وكان بهوه فوق بركة ماء عظيمة سقفها زجاج مملّس، فلما رأته حسبته ماءً فكشفت عن ساقيها، فقال سليمان: إنه صرح مملّس من زجاج. فلما بهرها الموقف وعرفت أنها كانت ضالّة قالت: رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين. ولم يذكر القرآن عنها بعدُ شيئاً، فلنسكت عما سكت عنه القرآن.", "h": ["جواز اختبار الأفراد إذا أريد إسناد أمر لهم لمعرفة قدرتهم العقلية والبدنية.", "بيان حصافة عقل بلقيس، ولذا أسلمت، وظهر ذلك في قولها: «كأنه هو».", "مضارّ التقليد، وما يترتّب عليه من التنكّر للعقل والمنطق.", "حرمة كشف المرأة ساقيها حتى ولو كانت كافرة، فكيف إذا كانت مسلمة.", "فضيلة الائتساء بالصالحين، كما ائتست بلقيس بسليمان في قولها: «وأسلمت مع سليمان لله رب العالمين»."], "k": "«وصدّها ما كانت تعبد من دون الله»… ذكاؤها لم يكفِ وحده حتى تركت ما ألِفته؛ فما الذي ألِفته ويصدّني عن الحق؟"}, {"lbl": "الآيات ٤٥ – ٤٩", "q": "وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحًا أَنِ ٱعۡبُدُواْ ٱللَّهَ فَإِذَا هُمۡ فَرِيقَانِ يَخۡتَصِمُونَ ﴿٤٥﴾ قَالَ يَٰقَوۡمِ لِمَ تَسۡتَعۡجِلُونَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِۖ لَوۡلَا تَسۡتَغۡفِرُونَ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٤٦﴾ قَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَـٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ﴿٤٧﴾ وَكَانَ فِي ٱلۡمَدِينَةِ تِسۡعَةُ رَهۡطٖ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ ﴿٤٨﴾ قَالُواْ تَقَاسَمُواْ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَٰدِقُونَ ﴿٤٩﴾", "w": [["أن اعبدوا الله", "بأن اعبدوا الله."], ["فريقان يختصمون", "طائفتان: مؤمنة موحّدة، وكافرة مشركة."], ["تستعجلون بالسيئة", "تطالبون بالعذاب قبل الرحمة."], ["لولا تستغفرون الله", "هلّا تطلبون المغفرة من ربكم بتوبتكم إليه."], ["اطّيّرنا بك", "تشاءمنا بك وبمن معك من المؤمنين."], ["طائركم عند الله", "ما يصيبكم من المكاره عند الله علمه."], ["بل أنتم قوم تُفتنون", "تُختبرون بالخير والشر."], ["تسعة رهط", "تسعة رجال ظلمة."], ["تقاسموا بالله", "تحالفوا بالله."], ["لنبيّتنّه وأهله", "لنقتلنّه والمؤمنين به ليلاً."], ["ما شهدنا مهلك أهله", "ما حضرنا قتله ولا قتل أهله."]], "m": "هذا بداية قصص صالح ﵇ مع ثمود، وضعاً لقريش أمام أحداث تمثّل حالهم مع نبيّهم: ولقد أرسلنا إلى ثمود أخاهم في النسب صالحاً أن اعبدوا الله وحده، فإذا هم فريقان: موحّدون ومشركون يختصمون. وطالبوه بالعذاب الذي يعدهم، فقال: يا قوم لمَ تستعجلون بالعذاب قبل الرحمة؟ هلّا تستغفرون الله بترك الشرك والمعاصي لعلكم ترحمون. قالوا: تشاءمنا بك وبمن معك. قال: ما يصيبكم من المكاره عند الله علمه وهو كائن لا محالة، وليست القضية تشاؤماً ولا تيامناً، بل أنتم قوم تُختبرون. وكان في مدينة الحِجر تسعة رجال يفسدون في الأرض بالكفر والمعاصي ولا يصلحون، وهم الذين تمالؤوا على عقر الناقة، قالوا في اجتماع خاص: ليحلف كل منكم بالله لنأتينّ صالحاً وأتباعه ليلاً فنقتلهم، ثم نقول لوليّ دمه: ما حضرنا مهلكه ولا مهلك أهله، وإنا لصادقون.", "h": ["تقرير نبوة النبي ﷺ.", "تقرير حقيقة أن الصراع بين الحق والباطل لا ينتهي إلا بانتهاء الباطل.", "حرمة التشاؤم والتيامن كذلك، ولم يُجز الشارع إلا التفاؤل.", "العمل بمعاصي الله تعالى هو الفساد في الأرض، والعمل بطاعته هو الإصلاح.", "تقرير أن المشركين يؤمنون بالله ولذا يحلفون به، ولم يُدخلهم ذلك في الإسلام لشركهم في عبادته غيره."], "k": "«لولا تستغفرون الله لعلكم تُرحمون»… بين يديّ طريق للرحمة أقصر من كل جدال؛ فهل أستغفر الآن؟"}, {"lbl": "الآيات ٥٠ – ٥٣", "q": "وَمَكَرُواْ مَكۡرٗا وَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ ﴿٥٠﴾ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِينَ ﴿٥١﴾ فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ﴿٥٢﴾ وَأَنجَيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿٥٣﴾", "w": [["ومكروا مكراً", "دبّروا طريقة خفية لقتل صالح والمؤمنين."], ["ومكرنا مكراً", "دبّرنا طريقة خفية لنجاة صالح والمؤمنين وإهلاك الظالمين."], ["وهم لا يشعرون", "بأنّا ندبّر لهم طريق هلاكهم."], ["بيوتهم خاوية", "فارغة ليس فيها أحد."], ["بما ظلموا", "بسبب ظلمهم، وهو الشرك والمعاصي."], ["لآية", "لعبرة."], ["وأنجينا الذين آمنوا", "صالحاً والمؤمنين."]], "m": "هذا نهاية قصص صالح مع ثمود: تقاسم التسعة على قتل صالح والمؤمنين ليلاً، ليحولوا في نظرهم دون العذاب الذي واعدهم به بعد ثلاثة أيام، فأتوا صالحاً وهو يصلي في مسجد له تحت الجبل، فسقطت عليهم صخرة من الجبل فأهلكتهم أجمعين، وهكذا مكر الله بهم وهم لا يشعرون، ثم أهلك القوم كلهم بالصيحة فأصبحوا في ديارهم جاثمين. فانظر يا رسولنا كيف كان عاقبة مكرهم: أنّا دمّرناهم وقومهم أجمعين، فتلك بيوتهم خاوية بسبب ظلمهم أنفسهم بالشرك وظلمهم صالحاً والمؤمنين، إن في ذلك لعلامة على قدرة الله وحسن تدبيره لقوم يعلمون. وأنجينا صالحاً والمؤمنين الذين آمنوا وكانوا طوال حياتهم يتّقون عقاب الله بطاعته وطاعة رسوله.", "h": ["تقرير قاعدة: «ولا يحيق المكر السيّئ إلا بأهله».", "تقرير أن ديار الظالمين مآلها الخراب، فالظلم يذر الديار بلاقع.", "الإيمان والتقوى هما سبب النجاة، لأن ولاية الله للعبد تتم بهما."], "k": "«فتلك بيوتهم خاوية بما ظلموا»… أمرّ على بيوت كانت عامرة؛ فهل أعمر بيتي بما يبقيه؟"}, {"lbl": "الآيتان ٥٤ – ٥٥", "q": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ ﴿٥٤﴾ أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ تَجۡهَلُونَ ﴿٥٥﴾", "w": [["ولوطاً", "واذكر لقومك لوطاً إذ قال لقومه."], ["لقومه", "سكان مدن عمورية وسدوم."], ["الفاحشة", "الخصلة القبيحة الشديدة القبح، وهي اللواط."], ["وأنتم تبصرون", "إذ كانوا يأتونها في أنديتهم عياناً بلا ستر."], ["قوم تجهلون", "تجهلون قبح ما تأتون وما يترتّب عليه من خزي وعذاب."]], "m": "هذا بداية قصص لوط ﵇: واذكر كما ذكرت صالحاً لوطاً إذ قال لقومه منكراً موبّخاً: أتأتون الفاحشة وأنتم تبصرون قبحها ببصائركم وأبصاركم، إذ كانوا يأتونها علناً؟ أئنّكم لتأتون الرجال شهوة من دون النساء، لا للعفّة ولا للولد، بل لقضاء الشهوة البهيمية، وفي الوقت نفسه آذيتم نساءكم فهضمتم حقوقهن؟ بل أنتم قوم تجهلون ما يجب عليكم لربكم من الإيمان والطاعة، وما يترتّب على العصيان من العقاب.", "h": ["بيان ما كان عليه قوم لوط من الفساد والهبوط العقلي والخلقي.", "تحريم فاحشة اللواط، وأنها أقبح شيء، وأن فاعلها أحطّ من البهائم.", "الجهل بالله تعالى وما يجب له من الطاعة هو سبب كل شر وفساد في الأرض، ولذا كان الطريق إلى إصلاح البشر تعريفهم بالله تعالى، حتى إذا عرفوه وآمنوا به أمكنهم أن يستقيموا على منهج الإصلاح."], "k": "«بل أنتم قوم تجهلون»… أصل الفساد جهل بالله؛ فكم أعرف ربي معرفةً تمنعني من معصيته؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;